@property
def _combined(self) -> IntervalSide:
    import numpy as np

    # Assuming `left` and `right` are always ndarray
    left = np.asarray(self.left._values).reshape(-1, 1)
    right = np.asarray(self.right._values).reshape(-1, 1)

    if needs_i8_conversion(left.dtype):
        # Use numpy's concatenate for ndarray
        comb = np.concatenate([left, right], axis=1)
        comb = comb.view("complex128")[:, 0]
    else:
        comb = (np.array(left.ravel(), dtype="complex128")) + (
            1j * np.array(right.ravel(), dtype="complex128")
        )
    return comb
